'use strict';
const PUSH_LABELS={urgent:['Nhờ mua thêm ngay','Thành viên bấm gửi: món, số lượng, cửa hàng, ghi chú.'],attendance:['Nhắc báo cơm','Khoảng giờ báo cơm, khi còn người chưa xác nhận.'],prep:['Chuẩn bị bữa tối','Nhắc sơ chế khi bữa tối chưa được ghi nhận đã nấu.'],shopping:['Việc đi chợ chưa xong','Có yêu cầu mua thêm trong hôm nay chưa hoàn thành.'],expiry:['Kiểm tra hạn dùng','Lô có hạn dùng bạn nhập trong hôm nay / ngày mai.'],receipt:['Nhớ nhập receipt','Đã tick mua hôm nay nhưng chưa có hóa đơn cùng ngày.'],budget:['Ngân sách tuần','Thông báo một lần mỗi tuần khi chi thực tế vượt mục tiêu.'],weekly:['Lên thực đơn tuần mới','Chủ Nhật khoảng 18:00, gợi ý chuẩn bị tuần tới.']};
let pushStatusCache={configured:false,publicKey:null,devices:[]},requestDraftId=null;
function pushDeviceId(){let id=familyStorage.getItem('bep-push-device-id');if(!id){id=uid();familyStorage.setItem('bep-push-device-id',id)}return id}
function pushProfile(){try{return JSON.parse(familyStorage.getItem('bep-push-profile')||'null')||{}}catch{return{}}}
async function refreshPushStatus(){if(!cloudConnection.connected)return;try{const res=await familyRequest('push-status');if(res.ok)pushStatusCache=await res.json()}catch{}}
async function pushSettings(){await refreshPushStatus();const profile=pushProfile(),supported='Notification'in window&&'PushManager'in window&&'serviceWorker'in navigator,permission='Notification'in window?Notification.permission:'unsupported',id=pushDeviceId();modal('Push: nhắc việc & người nhận',`<p class="hint"><b>Ai gửi?</b> Server Netlify gửi tự động theo lịch đã bật. Khi cần đồ gấp, một thành viên bấm “Nhờ mua thêm”, server chuyển nội dung đến người được chọn. Thiết bị nhận phải đăng ký trước.</p><div class="status-line"><span>Thiết bị này</span><span class="pill ${permission==='granted'?'':'orange'}">${{granted:'Đã cho phép',denied:'Đang chặn',default:'Chưa cấp quyền',unsupported:'Chưa hỗ trợ'}[permission]}</span></div><div class="status-line"><span>Lưu dữ liệu chung</span><span class="pill ${cloudConnection.connected?'':'orange'}">${cloudConnection.connected?'Đã kết nối Netlify':'Chưa kết nối Netlify'}</span></div>${!cloudConnection.available?'<div class="callout">Bản review không chạy Netlify Functions. Deploy gói trên Netlify, đặt FAMILY_PASSWORD và kết nối gia đình để dùng push thật.</div>':''}<form id="push-device-form"><div class="form-grid"><div class="field"><label for="push-member">Điện thoại này của ai?</label><select id="push-member">${state.members.map(m=>`<option value="${m.id}" ${profile.memberId===m.id?'selected':''}>${esc(m.name)}</option>`).join('')}</select></div><div class="field"><label for="push-label">Tên thiết bị</label><input id="push-label" maxlength="80" value="${esc(profile.label||'Điện thoại của tôi')}" placeholder="Ví dụ: iPhone của Mẹ"></div></div><div class="form-grid"><div class="field"><label for="push-role">${tr('Vai trò của bạn','Your role')}</label><select id="push-role">${[['both',tr('Nấu ăn & đi chợ','Cook & shopper')],['cook',tr('Chủ yếu nấu ăn','Mostly cooking')],['shopper',tr('Chủ yếu đi chợ','Mostly shopping')]].map(([v,n])=>`<option value="${v}" ${(profile.role||'both')===v?'selected':''}>${n}</option>`).join('')}</select></div><div class="field"><label for="push-language">${tr('Ngôn ngữ thông báo','Notification language')}</label><select id="push-language"><option value="vi" ${(profile.language||appLanguage)==='vi'?'selected':''}>Tiếng Việt</option><option value="en" ${(profile.language||appLanguage)==='en'?'selected':''}>English</option></select></div></div><h3>Những việc muốn nhận push</h3><div class="push-type-list">${Object.entries(PUSH_LABELS).map(([key,[name,note]])=>`<label class="checked-label"><input class="check push-type" type="checkbox" value="${key}" ${(profile.types?.[key]??['urgent','expiry','weekly'].includes(key))?'checked':''}><span>${name}<small style="display:block">${note}</small></span></label>`).join('')}</div><div class="form-grid topspace"><div class="field"><label for="push-quiet-start">Yên lặng từ</label><input id="push-quiet-start" type="time" required value="${profile.quietStart||state.preferences.quietStart||'21:00'}"></div><div class="field"><label for="push-quiet-end">Đến</label><input id="push-quiet-end" type="time" required value="${profile.quietEnd||state.preferences.quietEnd||'07:00'}"></div></div><label class="checked-label topspace"><input class="check" type="checkbox" id="push-urgent-bypass" ${profile.urgentBypass?'checked':''}>${tr('Cho phép yêu cầu khẩn đi qua giờ yên lặng','Allow explicitly urgent requests during quiet hours')}</label></form><p class="callout">${tr('Lịch tự động tối đa 2 thông báo/ngày/thiết bị. Vai trò lọc nhắc việc tự động: người nấu nhận sơ chế/hạn dùng/thực đơn; người đi chợ nhận mua đồ/hóa đơn/ngân sách. Báo cơm chỉ gửi người chưa báo. Yêu cầu trực tiếp chỉ gửi người được chọn.','Automatic reminders are limited to 2 per device per day. Roles filter automated tasks: cooks get prep/expiry/menu reminders; shoppers get shopping/receipt/budget reminders. Attendance reminders go only to pending members. Direct requests go only to selected recipients.')}</p><form id="push-times-form"><div class="form-grid">${[['attendanceTime',tr('Giờ nhắc báo cơm','Attendance time'),'10:30'],['prepReminderTime',tr('Giờ kiểm tra sơ chế','Prep review time'),'17:00'],['shoppingReminderTime',tr('Giờ nhắc yêu cầu mua','Shopping request time'),'09:00']].map(([key,label,time])=>`<div class="field"><label>${label}</label><input type="time" name="${key}" required value="${state.preferences[key]||time}"></div>`).join('')}</div><button class="btn" type="submit">${tr('Lưu giờ chung cho gia đình','Save family reminder times')}</button></form><p class="hint">Lịch tự động kiểm tra 15 phút/lần theo Australia/Sydney, có tính giờ mùa hè. Giờ yên lặng áp dụng mọi yêu cầu; chỉ yêu cầu khẩn có thể đi qua nếu người nhận cho phép. Thông báo bị tắt/yên lặng không được hẹn gửi bù; yêu cầu vẫn nằm trong danh sách. Thời điểm nhận và âm thanh còn phụ thuộc mạng, quyền thông báo và chế độ tập trung của điện thoại.</p><h3>Thiết bị đã đăng ký</h3>${pushStatusCache.devices.map(d=>`<div class="push-device-row">${esc(d.label)} · ${esc(state.members.find(m=>m.id===d.memberId)?.name||'Thành viên đã bỏ')}${d.deviceId===id?' · Thiết bị này':''}</div>`).join('')||'<p class="hint">Chưa có thiết bị nhận. Mỗi điện thoại cần mở app và bật push.</p>'}<p class="hint topspace">iPhone: thêm app vào Màn hình chính rồi mở từ biểu tượng trước khi bật push. Android: mở website HTTPS, cài PWA nếu trình duyệt yêu cầu.</p>`,`<button class="btn" data-feature="cloud-settings">Kết nối Netlify</button>${pushStatusCache.devices.some(d=>d.deviceId===id)?'<button class="btn" data-push-action="unsubscribe">Tắt thiết bị này</button>':''}<button class="btn" data-push-action="test" ${!cloudConnection.connected?'disabled':''}>${tr('Thử trên thiết bị này','Test this device')}</button><button class="btn primary" data-push-action="subscribe" ${!supported||!cloudConnection.connected?'disabled':''}>${pushStatusCache.devices.some(d=>d.deviceId===id)?'Lưu tùy chọn push':'Bật push thiết bị này'}</button>`,true)}
remindersModal=pushSettings;
function vapidBytes(base64){const padding='='.repeat((4-base64.length%4)%4),raw=atob((base64+padding).replace(/-/g,'+').replace(/_/g,'/'));return Uint8Array.from(raw,c=>c.charCodeAt(0))}
async function subscribeDevice(){if(!cloudConnection.connected){toast('Kết nối Netlify trước.',true);return}const profile={deviceId:pushDeviceId(),memberId:$('#push-member').value,label:$('#push-label').value.trim()||'Điện thoại gia đình',types:Object.fromEntries($$('.push-type').map(el=>[el.value,el.checked])),quietStart:$('#push-quiet-start').value,quietEnd:$('#push-quiet-end').value,role:$('#push-role').value,language:$('#push-language').value,urgentBypass:$('#push-urgent-bypass').checked};let permission=Notification.permission;if(permission==='default')permission=await Notification.requestPermission();if(permission!=='granted'){toast('Chưa được cấp quyền thông báo. Kiểm tra cài đặt của trình duyệt / iPhone.',true);return}try{const registration=await navigator.serviceWorker.getRegistration();if(!registration?.active){toast('Service Worker chưa sẵn sàng. Tải lại app rồi thử.',true);return}const keyResponse=await familyRequest('push-key',{method:'POST'});if(!keyResponse.ok)throw Error('Chưa tạo được khóa push trên Netlify.');const{publicKey}=await keyResponse.json();let subscription=await registration.pushManager.getSubscription();if(subscription){const expected=vapidBytes(publicKey),existing=subscription.options?.applicationServerKey;const bytes=existing?new Uint8Array(existing):null;if(!bytes||bytes.length!==expected.length||bytes.some((b,i)=>b!==expected[i])){await subscription.unsubscribe();subscription=null}}if(!subscription)subscription=await registration.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:vapidBytes(publicKey)});const response=await familyRequest('push-subscribe',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...profile,subscription:subscription.toJSON()})});if(!response.ok){const result=await response.json();throw Error(result.error||'Netlify chưa lưu được thiết bị nhận.')}familyStorage.setItem('bep-push-profile',JSON.stringify(profile));toast('Đã đăng ký thiết bị nhận push.');await pushSettings()}catch(error){toast(error.message||'Chưa bật được push. Mở app từ Màn hình chính trên iPhone.',true)}}
async function unsubscribeDevice(){try{const registration=await navigator.serviceWorker.getRegistration(),subscription=await registration?.pushManager.getSubscription();if(subscription)await subscription.unsubscribe();if(cloudConnection.connected)await familyRequest('push-unsubscribe',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({deviceId:pushDeviceId()})});familyStorage.removeItem('bep-push-profile');toast('Đã tắt nhận push trên thiết bị này.');await pushSettings()}catch(error){toast('Chưa hoàn tất tắt push. Kiểm tra cài đặt thông báo của điện thoại.',true)}}
async function requestItemForm(){await refreshPushStatus();requestDraftId=uid();const profile=pushProfile(),sender=profile.memberId||state.members[0].id,deviceMembers=new Set(pushStatusCache.devices.map(d=>d.memberId));modal('Quên ghi đồ? Nhờ mua thêm ngay',`<p class="hint">Nhập một yêu cầu rõ ràng. App thêm vào danh sách mua và giữ nội dung cho người mua; bạn chọn gửi push hoặc chia sẻ nếu chưa có thiết bị nhận.</p><form id="errand-form"><div class="field"><label for="errand-item">Cần mua gì?</label><input id="errand-item" name="item" maxlength="150" required placeholder="Ví dụ: rau mùi, đùi gà, sữa cho bé…"></div><div class="form-grid"><div class="field"><label for="errand-qty">Số lượng / cách mua</label><input id="errand-qty" name="qty" maxlength="80" required placeholder="2 cái / 1 bó / 500 g"></div><div class="field"><label for="errand-cost">Dự kiến tổng tiền ${currentCurrency(state)} (tùy chọn)</label><input id="errand-cost" name="cost" type="number" min="0" max="999999999" step=".01" placeholder="Chưa biết — để trống"></div></div><div class="field"><label for="errand-store">Mua tại đâu?</label><select id="errand-store" name="storeId"><option value="">Tùy nơi / chưa chọn</option>${(state.stores||[]).map(s=>`<option value="${s.id}">${esc(s.name)}${s.address?' · '+esc(s.address):''}</option>`).join('')}</select></div><div class="field"><label for="errand-note">Ghi chú để người mua hiểu ngay</label><textarea id="errand-note" name="note" maxlength="500" placeholder="Ví dụ: bó nhỏ, không có thì mua hành lá thay; cần cho bữa tối nay."></textarea></div><div class="field"><label for="errand-from">Người nhờ mua</label><select id="errand-from" name="fromId">${state.members.map(m=>`<option value="${m.id}" ${sender===m.id?'selected':''}>${esc(m.name)}</option>`).join('')}</select></div><h3>Gửi đến ai?</h3>${state.members.map(m=>`<label class="checked-label"><input class="check errand-target" type="checkbox" name="targets" value="${m.id}" ${deviceMembers.has(m.id)||!deviceMembers.size&&m.id!==sender?'checked':''}><span>${esc(m.name)} <small>${deviceMembers.has(m.id)?'có thiết bị đăng ký':'chưa có thiết bị push'}</small></span></label>`).join('')}<div class="field"><label for="errand-priority">${tr('Mức cần thiết','Priority')}</label><select id="errand-priority" name="priority"><option value="normal">${tr('Thông thường — tôn trọng giờ yên lặng','Normal — respect quiet hours')}</option><option value="urgent">${tr('Khẩn — người mua đang ở cửa hàng','Urgent — shopper is at the store')}</option></select></div><label class="checked-label topspace"><input class="check" id="errand-push" type="checkbox" checked> Gửi push ngay sau khi thêm</label><p class="hint">Tài khoản gia đình dùng chung mật khẩu; tên người gửi do bạn chọn, không phải xác thực tài khoản cá nhân. Yêu cầu thường cần bật “Việc đi chợ chưa xong”; yêu cầu khẩn cần bật “Nhờ mua thêm ngay”. Người nhận chọn giờ yên lặng và quyền cho phép khẩn đi qua.</p></form>`,`<button class="btn" data-push-action="settings">Cài người nhận</button><button class="btn primary" data-action="submit-form" data-id="errand-form">Thêm & gửi yêu cầu</button>`,true)}
function requestText(r){const store=getShop(state,r.storeId);return[`🛒 Nhờ mua thêm: ${r.qty} ${r.item}`,store?`📍 ${store.name}${store.address?' — '+store.address:''}`:'📍 Tùy cửa hàng thuận tiện',r.note?'📝 '+r.note:'',`Từ ${r.from||'Nhà mình'} · ${dateLabel(r.date)}`].filter(Boolean).join('\n')}
async function sendErrand(r,{first=false}={}){if(!cloudConnection.connected){modal('Đã thêm đồ, chưa gửi được push',`<p class="hint">Kết nối Netlify và đăng ký điện thoại người nhận trước. Yêu cầu vẫn nằm trong danh sách mua.</p><textarea id="errand-share-text" class="input" rows="6" readonly>${esc(requestText(r))}</textarea>`,`<button class="btn" data-push-action="share-request" data-id="${r.id}">Chia sẻ / Messenger</button><button class="btn primary" data-push-action="settings">Cài push</button>`);return}try{const response=await familyRequest('push-send',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({type:r.urgent?'urgent':'shopping',requestId:uid(),enTitle:`${r.from||'Family'} requests an item`,enBody:requestTextEnglish(r),title:`${r.from||'Nhà mình'} nhờ mua thêm`,body:requestText(r),targets:r.targets})});const result=await response.json();if(!response.ok)throw Error(result.error||'Netlify chưa gửi được push.');if(result.accepted){r.pushAccepted=result.accepted;r.pushAt=new Date().toISOString();save(`Đã gửi đến dịch vụ push cho ${result.accepted} thiết bị; chưa xác nhận đã đọc.`);render()}else{modal('Yêu cầu đã lưu; push chưa được nhận gửi',`<p>${['no_recipient','no_recipient_or_quiet'].includes(result.reason)?tr('Không có thiết bị phù hợp đang bật nhận, hoặc người nhận đang trong giờ yên lặng. Yêu cầu vẫn ở trong danh sách.','No eligible recipient is enabled, or recipients are in quiet hours. The request remains on the list.'):result.reason==='not_configured'?'Chưa có đăng ký push trên Netlify.':'Dịch vụ push chưa nhận được yêu cầu. Thử lại hoặc chia sẻ nội dung.'}</p><textarea class="input" rows="6" readonly>${esc(requestText(r))}</textarea>`,`<button class="btn" data-push-action="share-request" data-id="${r.id}">Chia sẻ nội dung</button><button class="btn primary" data-push-action="settings">Cài người nhận</button>`)}}catch(error){toast('Đã giữ yêu cầu trong danh sách; chưa gửi được push. '+error.message,true)}}
document.addEventListener('submit',async event=>{if(event.target.id!=='errand-form')return;event.preventDefault();const form=event.target,d=new FormData(form),v=Object.fromEntries(d),targets=d.getAll('targets');if(!targets.length){toast('Chọn ít nhất một người nhận.',true);return}const sender=state.members.find(m=>m.id===v.fromId),r={id:requestDraftId||uid(),item:v.item.trim(),qty:v.qty.trim(),storeId:v.storeId,note:v.note.trim(),from:sender?.name||'Nhà mình',targets,date:sydneyDate(),createdAt:new Date().toISOString(),done:false,pushAccepted:0,urgent:v.priority==='urgent'};if(!r.item||!r.qty)return;const shouldPush=$('#errand-push').checked;state.errands??=[];state.errands.push(r);const week=ensureWeek(state,monday(r.date));week.extras.push({id:uid(),name:r.item,qty:r.qty,cost:v.cost===''?0:+v.cost,costUnknown:v.cost==='',currency:currentCurrency(state),storeId:r.storeId,errandId:r.id,done:false});log(`Nhờ mua thêm ${r.qty} ${r.item}`);save('Đã thêm yêu cầu vào danh sách mua.');closeModal();view='shopping';location.hash='shopping';weekStart=monday(r.date);selectedDate=r.date;render();if(shouldPush)await sendErrand(r,{first:true})});
document.addEventListener('click',async event=>{const el=event.target.closest('[data-push-action]');if(!el)return;try{switch(el.dataset.pushAction){case'settings':await pushSettings();break;case'test':{const res=await familyRequest('push-test',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({deviceId:pushDeviceId()})});const result=await res.json();toast(res.ok&&result.accepted?tr('Dịch vụ push đã nhận thông báo thử cho thiết bị này.','Push service accepted the test for this device.'):tr('Đăng ký thiết bị nhận trước; chưa gửi được thử.','Register this device first; test was not sent.'),!result.accepted);break}case'subscribe':await subscribeDevice();break;case'unsubscribe':await unsubscribeDevice();break;case'request-item':await requestItemForm();break;case'resend-request':{const r=(state.errands||[]).find(r=>r.id===el.dataset.id);if(r)await sendErrand(r);break}case'share-request':{const r=(state.errands||[]).find(r=>r.id===el.dataset.id);if(r)await shareText(requestText(r));break}}}catch(error){toast(error.message||'Chưa thực hiện được thao tác push.',true)}});
render();

function requestTextEnglish(r){const shop=getShop(state,r.storeId);return[`${r.qty} ${r.item}`,shop?`${shop.name}${shop.address?' — '+shop.address:''}`:'Any convenient store',r.note||'',`From ${r.from||'Family'} · ${r.date}`].filter(Boolean).join('\n')}
document.addEventListener('submit',event=>{if(event.target.id!=='push-times-form')return;event.preventDefault();const values=Object.fromEntries(new FormData(event.target));if(!Object.values(values).every(v=>/^(?:[01]\d|2[0-3]):[0-5]\d$/.test(v)))return;Object.assign(state.preferences,values);save(tr('Đã lưu giờ nhắc theo Sydney.','Reminder times saved for Sydney.'))});
